package com.conferbot.sdk.core.i18n

import android.os.Build
import android.os.LocaleList
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.text.DateFormatSymbols
import java.util.Locale

/**
 * The SDK's own words, in the visitor's language. A port of the web
 * widget's conferbot-widget/src/ts/i18n.ts by way of the React Native SDK's
 * src/core/i18n.ts; the tables ([I18nStrings], generated by
 * scripts/sync-i18n.sh from RN's scripts/parity/i18n/strings.json) are the
 * web's keys and words, plus the `sdk.*` words only the SDKs draw.
 *
 *   t(key, vars)              the active language's string, {name} filled in
 *   tFor(lang, key, vars)     the same for a given language (pure, for tests)
 *   tPlural(base, n)          `base.one` for 1, else `base.other`
 *   resolveLanguage(setting, deviceLanguages)
 *                             a set language wins; "auto", unset or unknown
 *                             picks the first supported device language,
 *                             else English
 *   setWidgetLanguage(setting) when the bot's settings arrive, before the
 *                             chat is drawn (Conferbot does it)
 *
 * In an app "auto" means the phone's languages, most preferred first
 * (Android's LocaleList; the web reads navigator.languages). Only the SDK's
 * chrome lives here: what the owner wrote is shown as written, except the
 * stock English defaults a new bot is made with ([stockText], [ownerTextOr]).
 *
 * A key missing from a language falls back to English, then to the key
 * itself, so a half-finished translation never shows a blank.
 */
object I18n {
    const val EN = "en"
    val SUPPORTED: List<String> = listOf("en", "nl", "fr", "de", "es")

    /** Each language's own name, for pickers. */
    val LANGUAGE_NAMES: Map<String, String> = linkedMapOf(
        "en" to "English",
        "nl" to "Nederlands",
        "fr" to "Français",
        "de" to "Deutsch",
        "es" to "Español",
    )

    // Each table read once, the first time its language is drawn.
    private val tables = HashMap<String, Map<String, String>>()

    private fun tableOf(lang: String): Map<String, String> = synchronized(tables) {
        tables.getOrPut(lang) {
            val keys = I18nKeys.ALL
            val values = i18nValuesOf(lang)
            val m = HashMap<String, String>(keys.size * 2)
            for (i in keys.indices) values[i]?.let { m[keys[i]] = it }
            m
        }
    }

    /** Every key in the table (the web's, then sdk.*). */
    val keys: List<String> get() = I18nKeys.ALL.asList()

    /** One language's words by key (no fallback), for tests and the sync check. */
    fun dictionary(lang: String): Map<String, String> = tableOf(if (isSupported(lang)) lang else EN)

    private fun isSupported(v: String?) = v != null && v in SUPPORTED

    /** A stored setting: a supported code, else "auto" (old bots have none). */
    fun normalizeWidgetLanguage(raw: Any?): String {
        val v = (raw as? String)?.trim()?.lowercase(Locale.ROOT) ?: ""
        return if (isSupported(v)) v else "auto"
    }

    private val TAG_SPLIT = Regex("[-_]")

    /** "nl-BE" -> "nl"; anything unsupported -> null. */
    fun baseLanguageOf(tag: Any?): String? {
        if (tag !is String) return null
        val base = tag.trim().lowercase(Locale.ROOT).split(TAG_SPLIT)[0]
        return if (isSupported(base)) base else null
    }

    /** The language to draw in: the chosen one, or the first supported device language, or English. */
    fun resolveLanguage(setting: Any?, deviceLanguages: List<String>?): String {
        val chosen = normalizeWidgetLanguage(setting)
        if (chosen != "auto") return chosen
        for (tag in deviceLanguages.orEmpty()) baseLanguageOf(tag)?.let { return it }
        return EN
    }

    /**
     * The phone's languages, most preferred first, as BCP 47 ("de-DE"): the
     * whole LocaleList on API 24+, else the default locale. Repeats dropped.
     */
    fun deviceLanguages(): List<String> {
        val raw = mutableListOf<Locale>()
        try {
            if (Build.VERSION.SDK_INT >= 24) {
                val list = LocaleList.getDefault()
                for (i in 0 until list.size()) list.get(i)?.let { raw.add(it) }
            }
        } catch (_: Throwable) {
            // Not on a device (unit tests): the JVM's default below.
        }
        if (raw.isEmpty()) raw.add(Locale.getDefault())
        val out = mutableListOf<String>()
        for (l in raw) {
            val tag = runCatching { l.toLanguageTag() }.getOrNull()?.takeIf { it.isNotBlank() && it != "und" }
                ?: l.toString().replace('_', '-')
            if (tag.isNotBlank() && tag !in out) out.add(tag)
        }
        return out
    }

    private val PLACEHOLDER = Regex("\\{(\\w+)\\}")

    private fun fill(text: String, vars: Map<String, Any?>?): String {
        if (vars.isNullOrEmpty()) return text
        return PLACEHOLDER.replace(text) { m ->
            val v = vars[m.groupValues[1]]
            if (v == null) m.value else valueText(v)
        }
    }

    // Whole numbers without ".0", as JS writes them.
    private fun valueText(v: Any): String = when (v) {
        is Double -> if (v.isFinite() && v == Math.floor(v) && Math.abs(v) < 1e15) v.toLong().toString() else v.toString()
        is Float -> valueText(v.toDouble())
        else -> v.toString()
    }

    /** A string in a given language, {name} placeholders filled. */
    fun tFor(lang: String, key: String, vars: Map<String, Any?>? = null): String {
        val text = tableOf(if (isSupported(lang)) lang else EN)[key] ?: tableOf(EN)[key] ?: key
        return fill(text, vars)
    }

    private val _language = MutableStateFlow(EN)

    /** The language being drawn in, for screens that redraw when it changes. */
    val languageFlow: StateFlow<String> = _language.asStateFlow()

    @Volatile private var activeTag = EN

    private val listeners = mutableSetOf<(String) -> Unit>()

    /** Picks the language to draw in; returns it. */
    fun setWidgetLanguage(setting: Any?, languages: List<String> = deviceLanguages()): String {
        val before = _language.value
        val active = resolveLanguage(setting, languages)
        // A regional tag of the same language keeps its region for dates
        // (nl-BE writes dates the Belgian way).
        val regional = languages.firstOrNull { baseLanguageOf(it) == active }
        activeTag = if (regional != null && REGIONAL.matches(regional)) regional.replace('_', '-') else active
        _language.value = active
        if (before != active) synchronized(listeners) { listeners.toList() }.forEach { it(active) }
        return active
    }

    private val REGIONAL = Regex("^[a-zA-Z]{2}[-_][a-zA-Z]{2}$")

    /** The language being drawn in. */
    val language: String get() = _language.value

    /** A BCP 47 tag for dates (e.g. "nl-BE"). */
    val localeTag: String get() = activeTag

    /** The language's java.util.Locale (for date and number formats). */
    val locale: Locale get() = Locale.forLanguageTag(activeTag)

    /** Told when the language changes. Returns the unsubscribe. */
    fun onLanguage(fn: (String) -> Unit): () -> Unit {
        synchronized(listeners) { listeners.add(fn) }
        return { synchronized(listeners) { listeners.remove(fn) } }
    }

    /** A string in the active language. */
    fun t(key: String): String = tFor(language, key, null)

    /** A string in the active language, {name} placeholders filled. */
    fun t(key: String, vars: Map<String, Any?>?): String = tFor(language, key, vars)

    /** A string in the active language, vars as pairs. */
    fun t(key: String, vararg vars: Pair<String, Any?>): String = tFor(language, key, vars.toMap())

    /** "{n} thing" vs "{n} things": the `.one` key for 1, else `.other`. */
    fun tPlural(base: String, n: Number, vars: Map<String, Any?>? = null): String =
        t("$base.${if (n.toDouble() == 1.0) "one" else "other"}", mapOf<String, Any?>("n" to n) + (vars ?: emptyMap()))

    /**
     * The week's day names, Sunday first, in the widget's language: "long",
     * "short" (Sun, zo, dim.) or "narrow" (S, Z, D). English keeps the SDK's
     * own spellings for [english].
     */
    fun weekdayNames(style: String = "short", english: List<String>? = null): List<String> {
        if (language == EN && english != null) return english
        return try {
            val s = DateFormatSymbols.getInstance(locale)
            val names = if (style == "long") s.weekdays else s.shortWeekdays
            // DateFormatSymbols is 1-based (SUNDAY = 1).
            val list = (1..7).map { names[it] }
            if (style == "narrow") list.map { it.take(1).uppercase(locale) } else list
        } catch (_: Throwable) {
            english ?: listOf("Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat")
        }
    }

    /** Month names, January first, in the widget's language ("short": Jan, janv.). */
    fun monthNames(style: String = "short", english: List<String>? = null): List<String> {
        if (language == EN && english != null) return english
        return try {
            val s = DateFormatSymbols.getInstance(locale)
            val names = if (style == "long") s.months else s.shortMonths
            (0 until 12).map { names[it] }
        } catch (_: Throwable) {
            english ?: listOf("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
        }
    }

    private val TAGS = Regex("<[^>]*>")
    private val SPACES = Regex("\\s+")
    private val END = Regex("[.!]$")

    private fun plain(s: String) = END.replace(SPACES.replace(TAGS.replace(s, ""), " ").trim(), "").lowercase(Locale.ROOT)

    private fun isStock(value: String, key: String, stockEnglish: List<String>): Boolean {
        val v = plain(value)
        return (listOf(tFor(EN, key)) + stockEnglish).any { plain(it) == v }
    }

    /**
     * An owner field that may still hold the stock English default (stored by
     * an older dashboard): empty or the default is shown in the visitor's
     * language, a value the owner wrote themselves as written.
     */
    fun ownerTextOr(value: Any?, key: String, stockEnglish: List<String> = emptyList()): String {
        val v = value as? String
        if (v == null || plain(v).isEmpty() || isStock(v, key, stockEnglish)) return t(key)
        return v
    }

    /**
     * A field a new bot is created with in English ("Hi there 👋"): that exact
     * stock value is shown in the visitor's language. Empty stays empty, and
     * anything the owner wrote is theirs.
     */
    fun stockText(value: Any?, key: String, stockEnglish: List<String> = emptyList()): String {
        val v = value as? String ?: return ""
        if (v.isBlank()) return v
        return if (isStock(v, key, stockEnglish)) t(key) else v
    }
}

/** A string in the active language (web i18n t). */
fun t(key: String): String = I18n.t(key)

/** A string in the active language, {name} placeholders filled. */
fun t(key: String, vars: Map<String, Any?>?): String = I18n.t(key, vars)

/** A string in the active language, vars as pairs: t("queue.position", "n" to 3). */
fun t(key: String, vararg vars: Pair<String, Any?>): String = I18n.tFor(I18n.language, key, vars.toMap())

/** "{n} thing" vs "{n} things" in the active language. */
fun tPlural(base: String, n: Number, vars: Map<String, Any?>? = null): String = I18n.tPlural(base, n, vars)
